"""Fresh-source structural replay, explicitly records its training round budget."""
import argparse,json,subprocess,sys,time
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'results/replay';OUT.mkdir(parents=True,exist_ok=True)
p=argparse.ArgumentParser();p.add_argument('--secure-steps',type=int,required=True);args=p.parse_args();started=time.monotonic()
for label,command in [('range',[sys.executable,'verification/range_budget.py']),('training',[sys.executable,'verification/real_data.py','--download','--secure-steps',str(args.secure_steps)]),('chain',[sys.executable,'verification/real_chain.py','--faults'])]:
 with (OUT/(label+'.log')).open('w') as log:subprocess.run(command,cwd=ROOT,stdout=log,stderr=subprocess.STDOUT,check=True)
chain=json.loads((ROOT/'results/real-data/chain.json').read_text());train=json.loads((ROOT/'results/real-data/reference.json').read_text());publication=json.loads((ROOT/'results/real-data/publication.json').read_text());assert publication['source_training_session']==train['checkpoint']['directory'].split('/')[-1];assert chain['publication_session']==publication['session'];sessions=[step['session'] for step in train['secure_training']]+[publication['session']]+[r['session'] for r in chain['runs']]+[r['session'] for r in chain['faults']];assert len(sessions)==len(set(sessions))
result=dict(status='PASS_CLEAN_CORA_SHARED_TRAINING_TO_PROTECTED_HE_PROBABILITY',dimensions=train['dimensions'],secure_training_steps=args.secure_steps,reference_iterations=len(train['curves']),scope='Fresh Cora import, actual shared training checkpoint, secret f12-to-f7 publication, both activation variants, same-model MPC/HE and fault tests; round budget explicitly limited, not full learning-curve replication',sessions=sessions,model_ids=[m['model_id'] for m in publication['models']],protected_he_key_ids=[r['key_ids'] for r in chain['runs'] if r['route']=='he'],losses=[step['loss'] for step in train['secure_training']],chain_status=chain['status'],wire_bytes_training=sum(step['wire_bytes'] for step in train['secure_training']),wall_seconds=time.monotonic()-started)
(OUT/'summary.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2))
